guardrail.bad:
def append_item(item: str, items: list[str] = []) -> list[str]:
    items.append(item)
    return items  # same list reused on every call!

guardrail.good:
def append_item(item: str, items: list[str] | None = None) -> list[str]:
    if items is None:
        items = []
    items.append(item)
    return items

